package dev.algorithmlearning.api.dashboard.data; import dev.algorithmlearning.api.dashboard.application.*; import java.util.UUID; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository; @Repository public class JpaDashboardRepository implements DashboardRepository {private final NamedParameterJdbcTemplate jdbc;public JpaDashboardRepository(NamedParameterJdbcTemplate j){jdbc=j;}public DashboardCounts counts(UUID owner){var p=new MapSqlParameterSource("owner",owner);return jdbc.queryForObject("select count(*) total, count(*) filter(where difficulty='easy') easy,count(*) filter(where difficulty='medium') medium,count(*) filter(where difficulty='hard') hard,(select count(*) from problems p2 where p2.user_id=:owner and (not exists(select 1 from reviews r where r.problem_id=p2.id) or exists(select 1 from reviews r where r.problem_id=p2.id and r.reviewed_at=(select max(r2.reviewed_at) from reviews r2 where r2.problem_id=p2.id) and r.next_review_at<=now()))) due from problems where user_id=:owner",p,(rs,n)->new DashboardCounts(rs.getLong("total"),rs.getLong("easy"),rs.getLong("medium"),rs.getLong("hard"),rs.getLong("due")));}}
